window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["ollama"]={html:"<div class=\"own-ollama\">\n  <svg class=\"oll-sprite\" aria-hidden=\"true\" width=\"0\" height=\"0\">\n    <symbol id=\"oll-llama\" viewBox=\"0 0 120 120\">\n      <g fill=\"none\" stroke=\"currentColor\" stroke-width=\"3.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n        <path d=\"M40 52c-9 0-15 6-15 14 0 6 5 11 13 12\"/>\n        <path d=\"M78 30c-7 0-12 4-13 11-1 6 1 11 5 15-8 3-13 10-14 20\"/>\n        <path d=\"M78 30c3-7 10-10 15-7\"/>\n        <path d=\"M92 23c6-1 10 3 9 9-1 6-7 9-14 8\"/>\n        <path d=\"M85 42c-6 1-11 4-14 9\"/>\n        <path d=\"M63 57c-10 2-16 3-23 4-10 2-16 9-15 19 1 9 9 15 20 15h30c12 0 20-6 20-16 0-8-5-13-14-15-7-1-13-4-18-7\"/>\n        <path d=\"M44 95v13M60 95v13M82 95v13M96 95v13\"/>\n        <path d=\"M104 78c8-1 11 6 5 11\"/>\n        <circle cx=\"88\" cy=\"34\" r=\"1.7\" fill=\"currentColor\" stroke=\"none\"/>\n      </g>\n    </symbol>\n  </svg>\n\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"oll-nav\">\n    <a class=\"oll-brand\" href=\"#oll-top\" aria-label=\"Northwind home\">\n      <svg class=\"oll-llama oll-llama-sm\" aria-hidden=\"true\"><use href=\"#oll-llama\"/></svg>\n      <span>Northwind</span>\n    </a>\n    <nav class=\"oll-nav-links\" aria-label=\"Primary\">\n      <a href=\"#oll-models\">Regions</a>\n      <a href=\"#oll-docs\">Docs</a>\n      <a href=\"#oll-pricing\">Pricing</a>\n    </nav>\n    <label class=\"oll-search\">\n      <span class=\"oll-sr\">Search models</span>\n      <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n      <input type=\"search\" placeholder=\"Search dashboards, metrics\" autocomplete=\"off\">\n    </label>\n    <div class=\"oll-nav-right\">\n      <a class=\"oll-btn oll-btn-secondary oll-nav-signin\" href=\"#\">Sign in</a>\n      <a class=\"oll-btn oll-btn-primary\" href=\"#oll-top\">Download</a>\n      <button class=\"oll-burger\" type=\"button\" aria-label=\"Menu\" data-oll-burger>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 7h16M4 12h16M4 17h16\"/></svg>\n      </button>\n    </div>\n    <nav class=\"oll-drawer\" aria-label=\"Mobile\" data-oll-drawer hidden>\n      <a href=\"#oll-models\">Regions</a>\n      <a href=\"#oll-docs\">Docs</a>\n      <a href=\"#oll-pricing\">Pricing</a>\n      <a href=\"#\">Sign in</a>\n    </nav>\n  </header>\n\n  <!-- ── HERO ─────────────────────────────────────────────────────────── -->\n  <section class=\"oll-hero\" id=\"oll-top\" aria-labelledby=\"ollHeroH\">\n    <svg class=\"oll-llama oll-llama-lg\" aria-hidden=\"true\"><use href=\"#oll-llama\"/></svg>\n    <h1 id=\"ollHeroH\">The easiest way to run your operations analytics</h1>\n    <p class=\"oll-hero-sub\">Power Northwind with models that stay on your machines</p>\n    <div class=\"oll-install\" role=\"group\" aria-label=\"Install command\">\n      <code>curl -fsSL get.northwind.dev/install.sh | sh</code>\n      <button class=\"oll-copy\" type=\"button\" aria-label=\"Copy install command\" data-oll-copy>\n        <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"9\" y=\"9\" width=\"11\" height=\"11\" rx=\"2\"/><path d=\"M5 15V5a2 2 0 0 1 2-2h10\"/></svg>\n        <span data-oll-copy-label>Copy</span>\n      </button>\n    </div>\n    <div class=\"oll-hero-cta\">\n      <a class=\"oll-btn oll-btn-primary oll-btn-lg\" href=\"#oll-top\">Download Northwind</a>\n      <a class=\"oll-btn oll-btn-secondary oll-btn-lg\" href=\"#oll-docs\">Read the docs</a>\n    </div>\n  </section>\n\n  <!-- ── AUTOMATE ─────────────────────────────────────────────────────── -->\n  <section class=\"oll-split\" id=\"oll-docs\" aria-labelledby=\"ollAutoH\">\n    <div class=\"oll-split-copy\">\n      <h2 id=\"ollAutoH\">Automate your work</h2>\n      <p>Ask a question in plain language and Northwind writes the query, runs it across your warehouse, and pins the answer to the board your team already watches.</p>\n      <ul class=\"oll-chips\" aria-label=\"Example commands\">\n        <li><code class=\"oll-tag\">northwind ask \"why did throughput drop?\"</code></li>\n        <li><code class=\"oll-tag\">northwind sync --region ap-southeast</code></li>\n      </ul>\n    </div>\n    <div class=\"oll-terminal\" role=\"img\" aria-label=\"Terminal running Northwind\">\n      <div class=\"oll-terminal-bar\">\n        <span class=\"oll-dot oll-dot-r\"></span>\n        <span class=\"oll-dot oll-dot-y\"></span>\n        <span class=\"oll-dot oll-dot-g\"></span>\n      </div>\n      <pre class=\"oll-terminal-body\"><span class=\"oll-cmt\">$ northwind ask \"why did throughput drop?\"</span>\n<span class=\"oll-ok\">✔</span> Connected · 3 regions · 42k events/min\n<span class=\"oll-ok\">✔</span> Wrote query against <span class=\"oll-key\">ops.daily_throughput</span>\n<span class=\"oll-ok\">✔</span> Pinned answer to dashboard <span class=\"oll-key\">Ops Daily</span>\n<span class=\"oll-cmt\">→ Region ap-southeast ran 12.4% below target.</span>\n<span class=\"oll-cmt\">→ Root cause: night-shift handoff gap, 02:00–04:00.</span>\n<span class=\"oll-cmt\">$ <span class=\"oll-cursor\"></span></span></pre>\n    </div>\n  </section>\n\n  <!-- ── PRIVACY ──────────────────────────────────────────────────────── -->\n  <section class=\"oll-privacy\" aria-labelledby=\"ollPrivH\">\n    <svg class=\"oll-lock\" viewBox=\"0 0 48 48\" aria-hidden=\"true\">\n      <g fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n        <rect x=\"11\" y=\"21\" width=\"26\" height=\"19\" rx=\"3\"/>\n        <path d=\"M16 21v-5a8 8 0 0 1 16 0v5\"/>\n        <circle cx=\"24\" cy=\"30\" r=\"2.4\"/>\n        <path d=\"M24 32.5V36\"/>\n      </g>\n    </svg>\n    <h2 id=\"ollPrivH\">Your data stays yours</h2>\n    <p class=\"oll-privacy-copy\">Northwind runs the models locally by default — your numbers never leave the building unless you point it at a region you control. No training on your data, no silent uploads.</p>\n    <ul class=\"oll-bullets\">\n      <li>Local-first inference on hardware you own</li>\n      <li>Bring your own warehouse credentials</li>\n      <li>Full audit log for every query and export</li>\n    </ul>\n  </section>\n\n  <!-- ── PRICING ──────────────────────────────────────────────────────── -->\n  <section class=\"oll-pricing\" id=\"oll-pricing\" aria-labelledby=\"ollPriceH\">\n    <h2 class=\"oll-center\" id=\"ollPriceH\">Start local. Scale cloud.</h2>\n    <div class=\"oll-tiers\">\n      <article class=\"oll-tier\">\n        <svg class=\"oll-llama oll-llama-xs\" aria-hidden=\"true\"><use href=\"#oll-llama\"/></svg>\n        <h3>Free</h3>\n        <p class=\"oll-tier-note\">Run the whole board on one machine.</p>\n        <p class=\"oll-price\">$0</p>\n        <a class=\"oll-btn oll-btn-primary oll-tier-cta\" href=\"#oll-top\">Download</a>\n        <hr class=\"oll-tier-rule\">\n        <p class=\"oll-tier-eyebrow\">Everything you need to start</p>\n        <ul class=\"oll-features\">\n          <li><span aria-hidden=\"true\">✓</span> Local models on your hardware</li>\n          <li><span aria-hidden=\"true\">✓</span> Up to 5 dashboards</li>\n          <li><span aria-hidden=\"true\">✓</span> CSV and warehouse connectors</li>\n        </ul>\n      </article>\n      <article class=\"oll-tier\">\n        <svg class=\"oll-llama oll-llama-xs\" aria-hidden=\"true\"><use href=\"#oll-llama\"/></svg>\n        <h3>Pro</h3>\n        <p class=\"oll-tier-note\">For analysts who ship daily.</p>\n        <p class=\"oll-price\">$20</p>\n        <a class=\"oll-btn oll-btn-primary oll-tier-cta\" href=\"#oll-top\">Get Pro</a>\n        <hr class=\"oll-tier-rule\">\n        <p class=\"oll-tier-eyebrow\">Everything in Free, plus:</p>\n        <ul class=\"oll-features\">\n          <li><span aria-hidden=\"true\">✓</span> Unlimited dashboards</li>\n          <li><span aria-hidden=\"true\">✓</span> Scheduled refreshes</li>\n          <li><span aria-hidden=\"true\">✓</span> Anomaly alerts</li>\n          <li><span aria-hidden=\"true\">✓</span> Larger local models</li>\n        </ul>\n      </article>\n      <article class=\"oll-tier oll-tier-dark\">\n        <svg class=\"oll-llama oll-llama-xs\" aria-hidden=\"true\"><use href=\"#oll-llama\"/></svg>\n        <h3>Max</h3>\n        <p class=\"oll-tier-note\">Data-center grade, when you need it.</p>\n        <p class=\"oll-price\">$40</p>\n        <a class=\"oll-btn oll-btn-light oll-tier-cta\" href=\"#oll-top\">Get Max</a>\n        <hr class=\"oll-tier-rule\">\n        <p class=\"oll-tier-eyebrow\">Everything in Pro, plus:</p>\n        <ul class=\"oll-features\">\n          <li><span aria-hidden=\"true\">✓</span> Access larger models on data-center hardware</li>\n          <li><span aria-hidden=\"true\">✓</span> 50k events per minute per region</li>\n          <li><span aria-hidden=\"true\">✓</span> Priority support</li>\n        </ul>\n      </article>\n    </div>\n  </section>\n\n  <!-- ── FAQ ──────────────────────────────────────────────────────────── -->\n  <section class=\"oll-faq\" aria-labelledby=\"ollFaqH\">\n    <h2 class=\"oll-center\" id=\"ollFaqH\">Frequently asked questions</h2>\n    <div class=\"oll-faq-list\">\n      <div class=\"oll-faq-row\">\n        <h3>Where does Northwind store my data?</h3>\n        <p>On your own machines and in the warehouse you connect. Nothing is copied to us by default — the cloud tier is opt-in per region.</p>\n      </div>\n      <div class=\"oll-faq-row\">\n        <h3>Do I need a GPU to run it?</h3>\n        <p>A laptop with 16&nbsp;GB of memory runs the Free tier comfortably. Heavier models in the Max tier want a workstation or a data-center node.</p>\n      </div>\n      <div class=\"oll-faq-row\">\n        <h3>Can I bring my own metrics?</h3>\n        <p>Yes. Point Northwind at a warehouse, a CSV drop, or a webhook and it will model the table on the next sync.</p>\n      </div>\n      <div class=\"oll-faq-row\">\n        <h3>Is there a free trial of Max?</h3>\n        <p>Every plan starts with 14 days of Max, no card required. Downgrade or cancel any time from the account page.</p>\n      </div>\n    </div>\n  </section>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────── -->\n  <footer class=\"oll-foot\">\n    <nav class=\"oll-foot-links\" aria-label=\"Footer\">\n      <a href=\"#oll-top\">Download</a>\n      <a href=\"#\">Blog</a>\n      <a href=\"#oll-docs\">Docs</a>\n      <a href=\"#\">GitHub</a>\n      <a href=\"#\">Discord</a>\n      <a href=\"#\">Contact</a>\n      <a href=\"#\">Privacy</a>\n      <a href=\"#\">Terms</a>\n    </nav>\n    <span class=\"oll-copyright\">© 2026 Northwind</span>\n  </footer>\n</div>\n",css:"/* ══ OLLAMA — own layout for showcase.html ══════════════════════════════════\n   A paper-white, documentation-first marketing page: centre-aligned 36px hero,\n   a single black pill CTA, an inline install snippet, one dark pricing tier, and\n   a hand-drawn llama mascot as the only ornament. Everything interactive is a\n   full pill; the few pricing cards are 12px radius on a 1px hairline. Ported from\n   the DESIGN.md token vocabulary. Container queries mirror the documented\n   breakpoints (768 / 640 / 430) so Tablet (820) and Phone (390) reflow. */\n\n.own-ollama {\n  --primary: #000000;\n  --on-primary: #ffffff;\n  --ink: #000000;\n  --ink-deep: #090909;\n  --charcoal: #525252;\n  --body: #737373;\n  --mute: #a3a3a3;\n  --canvas: #ffffff;\n  --surface-soft: #fafafa;\n  --hairline: #e5e5e5;\n  --hairline-strong: #d4d4d4;\n  --on-dark: #ffffff;\n  --on-dark-mute: rgba(255, 255, 255, 0.7);\n  --surface-dark: #171717;\n  --focus-ring: rgba(59, 130, 246, 0.5);\n  --terminal-red: #ff5f56;\n  --terminal-yellow: #ffbd2e;\n  --terminal-green: #27c93f;\n\n  --display: 'SF Pro Rounded', 'Nunito', system-ui, -apple-system, sans-serif;\n  --ui: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;\n  --mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n\n  --r-sm: 6px;\n  --r-md: 8px;\n  --r-lg: 12px;\n  --r-full: 9999px;\n  --gut: clamp(20px, 5cqi, 40px);\n  --section: 88px;\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--ink);\n  font-family: var(--ui);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  -webkit-font-smoothing: antialiased;\n  border-radius: 13px;\n  overflow-x: clip;\n}\n.own-ollama *, .own-ollama *::before, .own-ollama *::after { box-sizing: border-box; }\n.own-ollama :focus-visible { outline: 2px solid var(--primary); outline-offset: 2px; border-radius: 4px; }\n.own-ollama .oll-sprite { position: absolute; width: 0; height: 0; overflow: hidden; }\n.own-ollama .oll-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }\n.own-ollama a { color: inherit; }\n.own-ollama h1, .own-ollama h2, .own-ollama h3 { margin: 0; font-family: var(--display); font-weight: 500; letter-spacing: 0; }\n.own-ollama p { margin: 0; }\n\n/* ── shared bits ──────────────────────────────────────────────────────── */\n.own-ollama .oll-center { text-align: center; }\n.own-ollama .oll-llama { color: var(--ink); }\n.own-ollama .oll-llama-sm { width: 26px; height: 26px; }\n.own-ollama .oll-llama-xs { width: 34px; height: 34px; }\n.own-ollama .oll-llama-lg { width: clamp(80px, 9cqi, 112px); height: clamp(80px, 9cqi, 112px); }\n\n.own-ollama .oll-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 36px; padding: 0 20px; border-radius: var(--r-full);\n  font-family: var(--ui); font-size: 14px; font-weight: 500; line-height: 1;\n  border: 1px solid transparent; text-decoration: none; white-space: nowrap;\n  transition: background-color .18s ease, color .18s ease, border-color .18s ease;\n}\n.own-ollama .oll-btn-lg { height: 44px; padding: 0 26px; font-size: 15px; }\n.own-ollama .oll-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-ollama .oll-btn-primary:hover { background: var(--ink-deep); }\n.own-ollama .oll-btn-secondary { background: var(--canvas); color: var(--ink); border-color: var(--hairline-strong); }\n.own-ollama .oll-btn-secondary:hover { border-color: var(--ink); }\n.own-ollama .oll-btn-light { background: var(--canvas); color: var(--ink); }\n.own-ollama .oll-btn-light:hover { background: var(--surface-soft); }\n\n/* ── nav ───────────────────────────────────────────────────────────────── */\n.own-ollama .oll-nav {\n  position: sticky; top: 68px; z-index: 30;\n  display: flex; align-items: center; gap: 20px; flex-wrap: wrap;\n  height: 56px; margin: 0 var(--gut); padding: 0;\n  background: rgba(255, 255, 255, .92);\n  backdrop-filter: saturate(1.4) blur(8px);\n  border-bottom: 1px solid var(--hairline);\n}\n.own-ollama .oll-brand {\n  display: inline-flex; align-items: center; gap: 8px;\n  font-family: var(--display); font-weight: 600; font-size: 17px;\n  text-decoration: none; color: var(--ink); white-space: nowrap;\n}\n.own-ollama .oll-nav-links { display: flex; align-items: center; gap: 20px; font-size: 14px; font-weight: 500; }\n.own-ollama .oll-nav-links a { color: var(--ink); text-decoration: none; }\n.own-ollama .oll-nav-links a:hover { text-decoration: underline; }\n.own-ollama .oll-search {\n  display: flex; align-items: center; gap: 8px; margin-left: auto;\n  width: min(360px, 34cqi); height: 36px; padding: 0 16px;\n  background: var(--surface-soft); border-radius: var(--r-full);\n}\n.own-ollama .oll-search svg { flex: none; width: 16px; height: 16px; fill: none; stroke: var(--body); stroke-width: 2; }\n.own-ollama .oll-search input { width: 100%; border: 0; background: none; color: var(--ink); font: inherit; font-size: 14px; }\n.own-ollama .oll-search input::placeholder { color: var(--mute); }\n.own-ollama .oll-search input:focus { outline: none; }\n.own-ollama .oll-search:focus-within { background: var(--canvas); box-shadow: 0 0 0 2px var(--focus-ring); }\n.own-ollama .oll-nav-right { display: flex; align-items: center; gap: 10px; }\n.own-ollama .oll-burger { display: none; place-items: center; width: 40px; height: 40px; border: 0; background: none; cursor: pointer; }\n.own-ollama .oll-burger svg { width: 22px; height: 22px; fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; }\n.own-ollama .oll-drawer { display: none; }\n\n/* ── hero ──────────────────────────────────────────────────────────────── */\n.own-ollama .oll-hero {\n  display: flex; flex-direction: column; align-items: center; text-align: center;\n  max-width: 720px; margin: 0 auto; padding: clamp(48px, 8cqi, 96px) var(--gut) var(--section);\n}\n.own-ollama .oll-hero h1 {\n  font-size: clamp(28px, 4cqi, 36px); font-weight: 500; line-height: 1.11;\n  max-width: 18ch; margin-top: 20px;\n}\n.own-ollama .oll-hero-sub { margin-top: 14px; font-size: 16px; color: var(--body); }\n.own-ollama .oll-install {\n  display: flex; align-items: center; gap: 12px; margin-top: 26px;\n  max-width: 100%; height: 48px; padding: 0 8px 0 20px;\n  background: var(--surface-soft); border-radius: var(--r-full);\n}\n.own-ollama .oll-install code {\n  font-family: var(--mono); font-size: 15px; color: var(--ink);\n  white-space: nowrap; overflow: hidden; text-overflow: ellipsis;\n}\n.own-ollama .oll-copy {\n  display: inline-flex; align-items: center; gap: 6px; flex: none;\n  height: 32px; padding: 0 14px; border: 0; border-radius: var(--r-full);\n  background: var(--canvas); color: var(--ink); font-size: 13px; font-weight: 500;\n  cursor: pointer; box-shadow: inset 0 0 0 1px var(--hairline-strong);\n}\n.own-ollama .oll-copy:hover { box-shadow: inset 0 0 0 1px var(--ink); }\n.own-ollama .oll-copy svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 1.8; }\n.own-ollama .oll-copy.done { color: #0a7d3c; }\n.own-ollama .oll-hero-cta { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; margin-top: 28px; }\n\n/* ── automate split ───────────────────────────────────────────────────── */\n.own-ollama .oll-split {\n  display: grid; grid-template-columns: 1fr 1fr; gap: clamp(24px, 4cqi, 56px);\n  align-items: center; max-width: 960px; margin: 0 auto; padding: 0 var(--gut);\n}\n.own-ollama .oll-split-copy h2 { font-size: clamp(20px, 2.6cqi, 24px); font-weight: 600; line-height: 1.33; }\n.own-ollama .oll-split-copy p { margin-top: 14px; font-size: 16px; color: var(--body); max-width: 46ch; }\n.own-ollama .oll-chips { list-style: none; margin: 22px 0 0; padding: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 10px; }\n.own-ollama .oll-tag {\n  display: inline-block; padding: 6px 12px; border-radius: var(--r-full);\n  background: var(--surface-soft); font-family: var(--mono); font-size: 13px; color: var(--ink);\n}\n.own-ollama .oll-terminal {\n  background: var(--canvas); border: 1px solid var(--hairline); border-radius: var(--r-lg);\n  padding: 16px; min-width: 0;\n}\n.own-ollama .oll-terminal-bar { display: flex; gap: 6px; margin-bottom: 14px; }\n.own-ollama .oll-dot { width: 12px; height: 12px; border-radius: var(--r-full); }\n.own-ollama .oll-dot-r { background: var(--terminal-red); }\n.own-ollama .oll-dot-y { background: var(--terminal-yellow); }\n.own-ollama .oll-dot-g { background: var(--terminal-green); }\n.own-ollama .oll-terminal-body {\n  margin: 0; font-family: var(--mono); font-size: 13.5px; line-height: 1.7;\n  color: var(--ink); white-space: pre-wrap; word-break: break-word; overflow-x: auto;\n}\n.own-ollama .oll-cmt { color: var(--mute); }\n.own-ollama .oll-ok { color: #0a7d3c; }\n.own-ollama .oll-key { color: var(--ink); }\n.own-ollama .oll-cursor {\n  display: inline-block; width: 8px; height: 15px; background: var(--ink);\n  vertical-align: -2px; animation: oll-blink 1.1s steps(1) infinite;\n}\n@keyframes oll-blink { 50% { opacity: 0; } }\n\n/* ── privacy ──────────────────────────────────────────────────────────── */\n.own-ollama .oll-privacy {\n  display: flex; flex-direction: column; align-items: center; text-align: center;\n  max-width: 640px; margin: 0 auto; padding: var(--section) var(--gut) 0;\n}\n.own-ollama .oll-lock { width: 48px; height: 48px; color: var(--ink); }\n.own-ollama .oll-privacy h2 { font-size: clamp(22px, 3cqi, 30px); font-weight: 500; line-height: 1.2; margin-top: 18px; }\n.own-ollama .oll-privacy-copy { margin-top: 14px; font-size: 16px; color: var(--body); max-width: 52ch; }\n.own-ollama .oll-bullets { list-style: none; margin: 26px 0 0; padding: 0; display: grid; gap: 10px; text-align: left; }\n.own-ollama .oll-bullets li { display: flex; gap: 10px; font-size: 15px; color: var(--charcoal); }\n.own-ollama .oll-bullets li::before { content: \"✓\"; color: var(--ink); font-weight: 600; }\n\n/* ── pricing ──────────────────────────────────────────────────────────── */\n.own-ollama .oll-pricing { max-width: 960px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-ollama .oll-pricing > h2 { font-size: clamp(24px, 3.2cqi, 30px); font-weight: 500; line-height: 1.2; }\n.own-ollama .oll-tiers { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; margin-top: 40px; }\n.own-ollama .oll-tier {\n  display: flex; flex-direction: column; padding: 32px;\n  background: var(--canvas); border: 1px solid var(--hairline); border-radius: var(--r-lg);\n}\n.own-ollama .oll-tier-dark { background: var(--surface-dark); border-color: var(--surface-dark); color: var(--on-dark); }\n.own-ollama .oll-tier h3 { margin-top: 14px; font-size: 20px; font-weight: 500; line-height: 1.4; }\n.own-ollama .oll-tier-note { margin-top: 6px; font-size: 14px; color: var(--body); }\n.own-ollama .oll-tier-dark .oll-tier-note { color: var(--on-dark-mute); }\n.own-ollama .oll-price { margin-top: 18px; font-family: var(--display); font-size: 30px; font-weight: 500; line-height: 1.2; }\n.own-ollama .oll-tier-cta { align-self: flex-start; margin-top: 20px; }\n.own-ollama .oll-tier-rule { width: 100%; border: 0; border-top: 1px solid var(--hairline); margin: 26px 0 20px; }\n.own-ollama .oll-tier-dark .oll-tier-rule { border-color: rgba(255, 255, 255, .16); }\n.own-ollama .oll-tier-eyebrow { font-size: 14px; font-weight: 500; color: var(--ink); }\n.own-ollama .oll-tier-dark .oll-tier-eyebrow { color: var(--on-dark); }\n.own-ollama .oll-features { list-style: none; margin: 16px 0 0; padding: 0; display: grid; gap: 10px; }\n.own-ollama .oll-features li { display: flex; gap: 10px; font-size: 14px; color: var(--charcoal); }\n.own-ollama .oll-tier-dark .oll-features li { color: var(--on-dark-mute); }\n.own-ollama .oll-features li > span { color: var(--ink); flex: none; }\n.own-ollama .oll-tier-dark .oll-features li > span { color: var(--on-dark); }\n\n/* ── faq ───────────────────────────────────────────────────────────────── */\n.own-ollama .oll-faq { max-width: 720px; margin: 0 auto; padding: var(--section) var(--gut) 0; }\n.own-ollama .oll-faq > h2 { font-size: clamp(24px, 3.2cqi, 30px); font-weight: 500; line-height: 1.2; }\n.own-ollama .oll-faq-list { margin-top: 34px; }\n.own-ollama .oll-faq-row { padding: 16px 0; border-bottom: 1px solid var(--hairline); }\n.own-ollama .oll-faq-row:first-child { border-top: 1px solid var(--hairline); }\n.own-ollama .oll-faq-row h3 { font-size: 18px; font-weight: 500; line-height: 1.56; font-family: var(--ui); }\n.own-ollama .oll-faq-row p { margin-top: 6px; font-size: 16px; color: var(--body); }\n\n/* ── footer ────────────────────────────────────────────────────────────── */\n.own-ollama .oll-foot {\n  display: flex; flex-wrap: wrap; align-items: center; justify-content: center; gap: 8px 20px;\n  max-width: 960px; margin: 0 auto; padding: 32px var(--gut) 40px;\n  border-top: 1px solid var(--hairline);\n}\n.own-ollama .oll-foot-links { display: flex; flex-wrap: wrap; justify-content: center; gap: 8px 20px; }\n.own-ollama .oll-foot-links a { font-size: 12px; color: var(--body); text-decoration: none; }\n.own-ollama .oll-foot-links a:hover { color: var(--ink); text-decoration: underline; }\n.own-ollama .oll-copyright { font-size: 12px; color: var(--body); }\n\n/* ── responsive (container queries mirror DESIGN.md breakpoints) ──────── */\n@container frame (max-width: 900px) {\n  .own-ollama .oll-split { grid-template-columns: 1fr; }\n  .own-ollama .oll-terminal { order: 2; }\n}\n@container frame (max-width: 768px) {\n  .own-ollama .oll-nav { height: 56px; }\n  .own-ollama .oll-nav-links { display: none; }\n  .own-ollama .oll-search { display: none; }\n  .own-ollama .oll-nav-signin { display: none; }\n  .own-ollama .oll-burger { display: grid; }\n  .own-ollama .oll-drawer {\n    display: grid; gap: 16px; width: 100%; order: 5; margin: 0;\n    padding: 16px 0 18px; border-top: 1px solid var(--hairline);\n    background: var(--canvas);\n  }\n  .own-ollama .oll-drawer[hidden] { display: none; }\n  .own-ollama .oll-drawer a { font-size: 15px; font-weight: 500; text-decoration: none; }\n  .own-ollama .oll-pricing > h2, .own-ollama .oll-faq > h2 { text-align: center; }\n  .own-ollama .oll-tiers { grid-template-columns: 1fr 1fr; }\n  .own-ollama .oll-tiers .oll-tier:last-child { grid-column: 1 / -1; }\n  .own-ollama { --section: 64px; }\n}\n@container frame (max-width: 640px) {\n  .own-ollama .oll-hero h1 { font-size: 28px; line-height: 1.15; }\n  .own-ollama .oll-install { height: auto; flex-wrap: wrap; padding: 12px 14px; border-radius: var(--r-lg); }\n  .own-ollama .oll-install code { white-space: normal; }\n  .own-ollama .oll-copy { margin-left: auto; }\n  .own-ollama .oll-tiers { grid-template-columns: 1fr; }\n  .own-ollama .oll-tiers .oll-tier:last-child { grid-column: auto; }\n}\n@container frame (max-width: 430px) {\n  .own-ollama { --section: 48px; }\n  .own-ollama .oll-hero-cta { width: 100%; }\n  .own-ollama .oll-hero-cta .oll-btn { flex: 1 1 auto; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-ollama *, .own-ollama *::before, .own-ollama *::after {\n    animation-duration: .001ms !important; animation-iteration-count: 1 !important;\n    transition-duration: .001ms !important;\n  }\n  .own-ollama .oll-cursor { animation: none; }\n}\n"};
/* ══ OLLAMA — own layout behaviour for showcase.html ═══════════════════════
   Registers window.OWN_LAYOUTS['ollama'].init(root). Wires the mobile menu
   drawer and the install-snippet copy button. init returns a cleanup function
   so unmounting removes every listener and timer. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  OWN['ollama'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var timers = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function $sel(s) { return root.querySelector(s); }

      var burger = $sel('[data-oll-burger]');
      var drawer = $sel('[data-oll-drawer]');
      if (burger && drawer) {
        on(burger, 'click', function () {
          var open = drawer.hasAttribute('hidden');
          if (open) drawer.removeAttribute('hidden');
          else drawer.setAttribute('hidden', '');
          burger.setAttribute('aria-expanded', String(open));
        });
        on(drawer, 'click', function (e) {
          if (e.target.closest('a')) { drawer.setAttribute('hidden', ''); burger.setAttribute('aria-expanded', 'false'); }
        });
      }

      var copy = $sel('[data-oll-copy]');
      var copyCode = $sel('.oll-install code');
      var copyLabel = $sel('[data-oll-copy-label]');
      if (copy && copyCode) {
        on(copy, 'click', function () {
          var text = copyCode.textContent || '';
          function done() {
            if (disposed) return;
            copy.classList.add('done');
            if (copyLabel) copyLabel.textContent = 'Copied';
            timers.push(window.setTimeout(function () {
              if (disposed) return;
              copy.classList.remove('done');
              if (copyLabel) copyLabel.textContent = 'Copy';
            }, 1600));
          }
          if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text).then(done, done);
          } else {
            done();
          }
        });
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        timers.forEach(function (id) { clearTimeout(id); });
      };
    }
  };
})();
